1	//! Tests for Innistrad Tier 9 Equipment cards:
2	//! Cobbled Wings, Mask of Avacyn, Silver-Inlaid Dagger, Sharpened Pitchfork,
3	//! Butcher's Cleaver, Wooden Stake.
4	
5	mod common;
6	
7	use common::*;
8	use mtg_engine::actions::{Action, Target};
9	use mtg_engine::cards::CardRegistry;
10	use mtg_engine::engine;
11	use mtg_engine::sba::check_state_based_actions_with_registry;
12	use mtg_engine::types::*;
13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	/// Helper: place a named equipment on the battlefield, already set as equipment.
19	fn equipment_on_battlefield(
20	    state: &mut mtg_engine::state::GameState,
21	    registry: &CardRegistry,
22	    name: &str,
23	    owner: mtg_engine::ids::PlayerId,
24	) -> mtg_engine::ids::ObjectId {
25	    let card_id = registry.get_id_by_name(name)
26	        .unwrap_or_else(|| panic!("Unknown card: {}", name));
27	    let id = state.create_object(card_id, owner, Zone::Battlefield, None, None);
28	    let obj = state.get_object_mut(id).unwrap();
29	    obj.name = name.into();
30	    obj.is_equipment = true;
31	    id
32	}
33	
34	/// Helper: equip an equipment to a creature by activating the ability.
35	fn equip(
36	    state: &mtg_engine::state::GameState,
37	    registry: &CardRegistry,
38	    equipment_id: mtg_engine::ids::ObjectId,
39	    creature_id: mtg_engine::ids::ObjectId,
40	) -> mtg_engine::state::GameState {
41	    let legal = engine::legal_actions(state, registry);
42	    let equip_action = legal.actions.iter().find(|a| {
43	        matches!(a, Action::ActivateAbility { object_id, targets, .. }
44	            if *object_id == equipment_id && targets == &[Target::Object(creature_id)])
45	    }).expect("should be able to equip the creature");
46	    engine::submit_action(state, equip_action, registry)
47	}
